// === Tab: mySketch ===
const sketch = (p) => {
    let min_width;

    let particles = [];

    let N_SCALE; 

    let PA = [];
    let PB = [];
    let PC = [];
    let PD = [];

    let N = 10000;

    let SEED;

    let XS;
    let YS;
    let GX;
    let GY;
    p.setup = () => {
        p.createCanvas(p.windowWidth, p.windowHeight);
        min_width = p.min(p.width, p.height);

        p.background(0);

        SEED = p.random()*998244353;

        p.randomSeed(SEED);
        p.noiseSeed(SEED); 

        XS = p.random(1.5, 1.7);
        YS = p.random(1.5, 1.7);
        N_SCALE = p.random(15, 50);

        for(let i=0;i<3;++i){
            PA.push(p.random(0.1, 0.5)); 
            PB.push(p.random(0.1, 0.5)); 
            PC.push(p.random(0.1, 1)); 
            PD.push(p.random(0.1, 0.5)); 
        }

        GX = 0;
        GY = 0;
        for(let i=0;i<N;++i){
            particles.push(new Particle(
                p.random(-1, 1)* XS,
                p.random(-1, 1)* YS,
                N_SCALE,
                min_width / 2 * .65
            ));
        }
    };

    p.windowResized = () => {
        p.resizeCanvas(p.windowWidth, p.windowHeight);
        min_width = p.min(p.width, p.height);

        particles.splice(0, particles.length);
        p.randomSeed(SEED);
        p.noiseSeed(SEED); 

        p.blendMode(p.BLEND);
        p.background(0);

        XS = p.random(1.5, 1.7);
        YS = p.random(1.5, 1.7);
        N_SCALE = p.random(15, 50);

        for(let i=0;i<3;++i){
            PA.push(p.random(0.1, 0.5)); 
            PB.push(p.random(0.1, 0.5)); 
            PC.push(p.random(0.1, 1)); 
            PD.push(p.random(0.1, 0.5)); 
        }

        GX = 0;
        GY = 0;
        for(let i=0;i<N;++i){
            particles.push(new Particle(
                p.random(-1, 1) * XS,
                p.random(-1, 1) * YS,
                N_SCALE,
                min_width / 2 * .65
            ));
        }
    }


    p.draw = () => {
        p.blendMode(p.ADD);
        p.push();
        p.translate(p.width/2, p.height/2);
        for(let i=0;i<N;++i){
            particles[i].update();
            particles[i].display();
        }
        p.pop();
    };

    p.keyPressed = () => {
        if(p.key == 's') {
            p.save("midnight_tunnel.png");
        }
    }

    class Particle {
        pos;
        velocity;
        acceleration;
        noise_scale;
        color;
        max_speed = 0.003;
        min_speed = 0.0001;

        width;
        constructor(x, y, ns, w) {
            this.pos = p.createVector(y, x);

            this.noise_scale = ns;

            this.velocity = p.createVector(0,0);
            this.acceleration = p.createVector(0,0);

            let dt = 1- p.sqrt(y*y/YS/YS + x*x/XS/XS);
            this.color = p.color(
                p.int(palette(PA[0], PB[0], PC[0], PD[0], p.abs(this.pos.x)) * 255 + 510) % 255,
                p.int(palette(PA[1], PB[1], PC[1], PD[1], p.abs(this.pos.y)) * 255 + 510) % 255,
                p.int(palette(PA[2], PB[2], PC[2], PD[2], p.sqrt(this.pos.x*this.pos.x+this.pos.y*this.pos.y)) * 255 + 510) % 255,
                150 - dt*140
            );

            this.width = w;
        }

        update(){
            let po = this.trans(this.pos);
            let nx = p.noise(p.abs(po.x)*this.noise_scale) - .5;
            let ny = p.noise(p.abs(po.x)/(po.y)*this.noise_scale) - .5;
            //let ny = p.noise(po.y*this.noise_scale) - .5;
            this.acceleration = p.createVector(
                nx,
                ny
            );

            this.velocity.add(this.acceleration);
            let speed = this.velocity.mag();
            this.velocity.normalize().mult(p.max(this.min_speed, p.min(speed, this.max_speed)));

            this.pos.add(this.velocity);

            this.acceleration.mult(0);
        }
        trans(po){
            let sgy = po.y < 0 ? -1: 1;
            let ret = p.createVector(
                p.atan2((po.y-GX), (po.x-GY)) / p.PI,
                p.sqrt(po.mag())*sgy
            );
            return ret;
        }
        display(){
            p.strokeWeight(this.width/200);
            p.stroke(this.color);

            p.point(
                this.pos.y * this.width,
                this.pos.x * this.width,
            )
        }
    }

    function palette(a, b, c, d, x) {
        return a + b * p.abs(p.cos(p.TWO_PI * c * x + d));
    }

};

new p5(sketch);

